import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.AddPainting{EntityUniqueID: -5, EntityRuntimeID: 300, Position: mgl32.Vec3{1, 2, 3},
#   Direction: -1, Title: "kebab"}
GOLDEN = bytes.fromhex("09ac020000803f000000400000404001056b65626162")

# generated by gophertunnel b8bd735:
# packet.AddPainting{EntityRuntimeID: 4294967296}
WIDE_RUNTIME_ID = bytes.fromhex("0080808080100000000000000000000000000000")

GOLDENS = [
    pytest.param(
        v2225.AddPaintingPacket(
            entity_id=-5, runtime_id=300, pos=v2225.Vec3(x=1.0, y=2.0, z=3.0), dir=-1, motif="kebab"
        ),
        GOLDEN,
        id="full",
    ),
    pytest.param(
        v2225.AddPaintingPacket(runtime_id=4294967296),
        WIDE_RUNTIME_ID,
        id="wide-runtime-id-and-empty-motif",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_add_painting_is_packet_22(version):
    assert version.packets[22] is version.AddPaintingPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_painting_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_add_painting_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
